from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent

def tag(t):return f'<span class="tag">{t}</span>'
def btn(t,secondary=False):return f'<button class="button {"secondary" if secondary else ""}" type="button">{t}</button>'
def label(t):return f'<p class="eyebrow">{t}</p>'
def heading(t,k=''):return (label(k) if k else '')+f'<h2>{t}</h2>'
def card(title,desc,num='01',light=False):return f'<article class="card {"paper" if light else ""}"><span class="number">{num} /</span><h3>{title}</h3><p>{desc}</p><span class="textlink">Explorar <span aria-hidden="true">↗</span></span></article>'
def row(title,sub,tail='↗'):return f'<div class="row"><div><h3>{title}</h3><p>{sub}</p></div><span class="rowtail">{tail}</span></div>'
mark='<svg class="mark" viewBox="0 0 48 48" aria-hidden="true"><path d="M3 39h13V27h12V15h14V3M3 47h22V35h12V23h10M3 29h4V17h13V5" fill="none" stroke="currentColor" stroke-width="3"/></svg>'
logo=f'<div class="logo">{mark}<span>Paynalton<span class="copper">.</span></span></div>'
def scene():return '<div class="scene" role="img" aria-label="Estudio de composición: planos de obsidiana, líneas de cobre y órbitas"><div class="orbit one"></div><div class="orbit two"></div><div class="slab a">'+mark+'</div><div class="slab b">'+mark+'</div><div class="slab c">'+mark+'</div><span class="sphere"></span><div class="plinth"></div><span class="scene-caption">CÓDIGO / PENSAMIENTO / PERSONAS</span></div>'
widgets=[]
def add(n,title,group,body,note,state='Ahora',variant=''):
 widgets.append(dict(id=f'W{n:02}',title=title,group=group,body=body,note=note,state=state,variant=variant))
add(1,'Salto al contenido','Navegación',f'<div class="skip-demo"><a href="#sample-content" class="skiplink">Saltar al contenido <span>↓</span></a><div class="muted-bar">{logo}<span>Navegación principal</span></div><div id="sample-content" tabindex="-1" class="outlined">{label("CONTENIDO PRINCIPAL")}<h2>El recorrido comienza aquí.</h2></div></div>','Estado visible al recibir foco. Contorno doble de alto contraste; el enlace lleva al contenido y desplaza el foco.')
add(2,'Marca y acceso al inicio','Navegación',f'<div class="brand-large">{logo}{label("DESARROLLO · IDEAS · CREACIÓN EDITORIAL")}</div><div class="divider"></div><div class="flex">{logo}<span class="small muted">Versión compacta / cabecera</span></div>','Marca tipográfica con greca abierta. El conjunto funciona como un único enlace a Inicio.')
add(3,'Navegación principal y móvil','Navegación',f'<div class="navbar">{logo}<nav><a class="active" href="#demo">Proyectos</a><a href="#demo">Trayectoria</a><a href="#demo">Obra y pensamiento</a><a href="#demo">Sobre mí</a><a href="#demo">Contacto</a></nav><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-menu">Menú ☰</button></div><div id="mobile-menu" class="mobile-menu" hidden>'+''.join(row(x,'', '↗') for x in ['Proyectos','Trayectoria','Obra y pensamiento','Sobre mí','Contacto'])+'</div><div class="nav-preview">'+label('SECCIÓN ACTIVA')+'<h2>Proyectos</h2><p>La navegación acompaña el contenido, sin competir con él.</p></div>','Subrayado cobre para sección activa. En móvil, menú desplegable; Escape cierra y devuelve el foco.')
add(4,'Selector: espacio reservado','Navegación',f'<div class="flex">{logo}<span class="locale-chip">ES <span aria-hidden="true">⌄</span></span></div><div class="divider"></div><div class="compact">{heading("Un control discreto.","RESERVA DE DISEÑO")}<p>La entrega actual conserva el contenido en español.</p></div>','Estudio de tamaño y alineación del control. No se incorpora un selector activo en esta etapa.','Fuera de esta etapa')
add(5,'Buscador','Navegación',heading('Encuentra una idea.','EXPLORAR')+'<label class="search-label">Buscar en el sitio<input type="search" data-search placeholder="Proyectos, publicaciones y temas" value=""></label><div class="search-items">'+row('Pipila','PROYECTO · Integración de sistemas')+row('Onix','PROYECTO · Modernización')+row('Cuando la tostadora te responde','OBRA · Pensamiento e IA')+'</div><p class="no-search" hidden>No encontramos coincidencias.</p>','Panel global y página de resultados comparten estilo. La muestra filtra tres entradas locales; el motor final se implementará con el sitio.')
add(6,'Migas de pan','Navegación','<nav class="crumbs" aria-label="Ruta de navegación"><a href="#demo">Inicio</a><span>/</span><a href="#demo">Proyectos</a><span>/</span><strong aria-current="page">Pipila</strong></nav><div class="divider"></div>'+heading('Pipila','INTEGRACIÓN DE SISTEMAS')+'<p>Siempre hay un camino de regreso a la colección.</p>','Jerarquía breve; separadores discretos y destino actual sin enlace. Se adapta por salto de línea.')
add(7,'Preferencias visuales','Navegación',heading('A tu ritmo.','PREFERENCIAS')+'<div class="settings"><label>Reducir movimiento<input type="checkbox" role="switch" checked></label><p>Transiciones suaves y sin desplazamientos continuos.</p><label>Desactivar escena 3D<input type="checkbox" role="switch"></label><p>Conservar la composición estática del taller.</p></div>','Interruptores con etiqueta y estado visible. En esta propuesta son controles de muestra; la escena de diseño no tiene animación.')
add(8,'Perfiles sociales','Contacto',heading('Otros lugares para conversar.','ENCONTRARNOS')+'<div class="social-grid">'+''.join(f'<a href="{u}"><span>{name}</span><span>↗</span><small>{d}</small></a>' for name,u,d in [('LinkedIn','https://www.linkedin.com/in/paynalton','Trayectoria y colaboración'),('GitHub','https://github.com/paynalton','Código y contribuciones'),('Reddit','https://www.reddit.com/user/paynalton3/','Ideas y conversaciones'),('TikTok','https://www.tiktok.com/@paynalton','Otros espacios')])+'</div>','Enlaces identificados por nombre y propósito; sin feeds ni contadores. Los destinos reales abren sus páginas públicas.')
add(9,'Presentación profesional','Portada',f'<div class="hero">{label("FULLSTACK / ARQUITECTURA / IA APLICADA")}<h1>Desarrollo software,<br>conecto ideas y<br><em>resuelvo problemas.</em></h1><p>Soy Paynalton, aunque casi todos me llaman Pay. Desarrollo software, diseño soluciones y acompaño a equipos.</p><div class="actions">{btn("Conocer mis proyectos ↗")}{btn("Hablemos",True)}</div></div>','Titular del documento editorial. Jerarquía fuerte, texto breve y dos acciones. Sin contadores ni títulos añadidos.')
add(10,'Escena del taller','Portada',f'<div class="scene-layout"><div>{heading("Ideas que toman forma.","ESTUDIO DE COMPOSICIÓN")}<p>Planos de obsidiana, un núcleo de cobre y una órbita que reúne las piezas.</p>{tag("Alternativa estática")}</div>{scene()}</div>','Estudio gráfico construido con CSS y SVG; no es todavía WebGL. Define composición, material y alternativa inmóvil para la implementación.','Ahora','wide')
add(11,'Tarjetas de contenido','Catálogos','<div class="sectionline">PROYECTOS SELECCIONADOS <span>01—03</span></div><div class="cards">'+card('Pipila','Integración modular y procesamiento asíncrono.','01')+card('Onix','Modernizar una operación que sigue en marcha.','02')+card('GUACAMAYA','Creación editorial con personas y agentes.','03')+'</div><div class="divider"></div><div class="paper editorial-tile">'+label('BIBLIOTECA / EJEMPLO CONFIGURABLE')+'<h2>Una pregunta abre<br>otra forma de pensar.</h2><p>Variante editorial para presentar una obra seleccionada.</p><span class="textlink">Abrir lectura ↗</span></div>','Familia común con variantes profesional y editorial. Orden y selección configurables; la muestra literaria no es una obra del autor.')
add(12,'Recorridos por interés','Exploración',heading('Elige un punto de partida.','RECORRIDOS')+'<div class="cards">'+card('Construir sistemas','Proyectos de integración y modernización.','01')+card('Acompañar equipos','Decisiones, liderazgo y formas de trabajo.','02')+card('Pensar y escribir','Lecturas, preguntas y creación editorial.','03',True)+'</div>','Recorridos editoriales manuales; cada ruta explica qué ofrece. No son recomendaciones personalizadas.','Posterior')
add(13,'Invitación y continuación','Portada','<div class="invitation">'+label('COMENZAR UNA CONVERSACIÓN')+'<h2>¿Qué intentas<br><em>resolver?</em></h2><p>Cuéntame en qué punto estás y qué esperas conseguir.</p>'+btn('Hablemos del proyecto ↗')+'<div class="divider"></div><span class="textlink">← Seguir explorando proyectos</span></div>','Una acción principal de cobre y continuación secundaria. Sin promesas de respuesta ni formularios.')
add(14,'Filtros de contenido','Catálogos',heading('Distintas formas de construir.','PROYECTOS')+'<div class="filterbar"><label>Tipo<select><option>Todos los proyectos</option><option>Herramientas propias</option></select></label><label>Tema<select><option>Integración de sistemas</option><option>Todos los temas</option></select></label></div><div class="chips"><button class="tag selected">Integración de sistemas ×</button><button class="textbutton" data-clear>Quitar filtros</button></div><div class="cards">'+card('Pipila','API modular para conectar servicios.')+card('Onix','ERP para integrar una operación.','02')+'</div>','Etiquetas siempre visibles sobre controles. Selección y acción de limpiar; en móvil se apilan sin crear paneles anidados.')
add(15,'Resultados y estados','Catálogos','<div class="resultbar"><strong>2 proyectos</strong><span>Integración de sistemas</span></div><div class="states"><article>'+label('SIN COINCIDENCIAS')+'<h3>No encontramos coincidencias.</h3><p>Prueba otras palabras o quita algún filtro.</p>'+btn('Quitar filtros',True)+'</article><article>'+label('ERROR DE CARGA')+'<h3>No pudimos cargar la búsqueda.</h3><p>Puedes explorar las categorías o intentarlo de nuevo.</p>'+btn('Volver a intentar',True)+'</article></div>','Se muestran dos estados alternativos para revisión; nunca aparecerían juntos en una página real. Carga, error y vacío son distintos.')
add(16,'Paginación','Catálogos',heading('Continúa explorando.','ARCHIVO')+'<nav class="pagination" aria-label="Paginación"><button aria-label="Página anterior">←</button><button aria-current="page">1</button><button>2</button><button>3</button><span>…</span><button>8</button><button aria-label="Página siguiente">→</button></nav><p class="small muted">Página 1 de 8 · Ejemplo de archivo extenso</p>','Botones explícitos, sin desplazamiento infinito. Cifras ilustrativas; se añade únicamente cuando el volumen lo justifique.','Posterior')
add(17,'Ficha de participación','Proyectos',heading('Delta Commerce','ARQUITECTURA Y CONSULTORÍA')+'<div class="factgrid"><div><small>PARTICIPACIÓN</small><h3>Diseño de la solución</h3></div><div><small>ALCANCE</small><h3>Arquitectura y consultoría</h3></div><div><small>CONTEXTO</small><h3>Extensión de Delta</h3></div><div><small>ESTADO</small><h3>En uso en una tienda</h3></div></div><p class="callout">Mi participación se concentró en el diseño y la consultoría, sin intervenir en el desarrollo.</p>','Datos recientes del propietario. La ficha diferencia participación, alcance y estado sin inventar métricas.')
add(18,'Galería y visor de evidencias','Proyectos',heading('Una decisión, su contexto.','EVIDENCIAS / EJEMPLO')+'<div class="evidence-grid"><div class="diagram-mini"><span>Interfaz</span><b>→</b><span>Servicio</span><b>→</b><span>Datos</span></div><aside>'+label('01 / DIAGRAMA ILUSTRATIVO')+'<h3>Separación de responsabilidades</h3><p>Una muestra para estudiar el visor. No representa la arquitectura de un cliente.</p>'+btn('Ampliar ↗',True)+'</aside></div>','Superficie para evidencias con descripción y control de apertura. El visor es una propuesta visual, no un acceso a material privado.','Posterior')
add(19,'Visor de arquitectura','Proyectos',heading('Comprender las conexiones.','ARQUITECTURA / EJEMPLO')+'<div class="architecture"><div>Interfaz pública</div><span>↓</span><div class="focus-node">Recepción de solicitudes</div><span>↓</span><div class="branches"><div>Procesamiento</div><div>Registro de estado</div></div></div><p class="small muted">Diagrama conceptual para probar la presentación; no documenta un sistema real.</p>','Nodos sobrios, foco jade y conectores cobre. La descripción textual acompaña la ampliación.','Posterior')
add(20,'Capacidades con evidencia','Trayectoria',heading('Capacidades que se pueden recorrer.','EXPERIENCIA')+row('Integración de sistemas','Pipila · Separar la interfaz del procesamiento')+row('Modernización','Onix · Evolución de código e infraestructura')+row('Liderazgo técnico','SoDigital · Coordinación y formación de equipos'),'Cada capacidad conduce a una aportación concreta. Sin barras, estrellas ni porcentajes de dominio.')
add(21,'Cronología profesional','Trayectoria',heading('Un recorrido que sigue creciendo.','TRAYECTORIA')+'<div class="timeline"><article><small>2025 — ACTUALIDAD</small><div><h3>Freeway</h3><p class="copper">Desarrollador</p><p>Desarrollo, arquitectura y operación en un equipo de ingeniería de plataformas.</p></div></article><article><small>2020 — 2025</small><div><h3>SoDigital</h3><p class="copper">Gerente de Desarrollo</p><p>Coordinación de equipos, arquitectura y entrega de soluciones.</p><details><summary>Ver contribuciones</summary><p>Participación directa en Winner y creación de la base de Pipila.</p></details></div></article></div>','Línea vertical sin alternancia. Etapas enlazables; detalles expandibles sin ocultar puesto y período.')
add(22,'Acceso al CV','Trayectoria',f'<div class="cv-sheet">{label("PERFIL PROFESIONAL")}<h2>Paynalton</h2><p>Desarrollo fullstack<br>Arquitectura · Liderazgo técnico</p><div class="divider"></div><div class="cv-lines"></div></div><div class="actions">{btn("Descargar CV ↓")}{btn("Consultar versión web ↗",True)}</div>','Muestra de composición. El CV se actualizará después de terminar el sitio; estos controles son solo de demostración y no enlazan a un archivo inexistente.','Después del sitio')
add(23,'Ficha editorial de obra','Lectura','<div class="paper editorial-header">'+label('LECTURA / EJEMPLO CONFIGURABLE')+'<h1>Una pregunta<br>al comienzo.</h1><p class="book-subtitle">Muestra de composición para una pieza breve.</p><div class="divider"></div><div class="flex"><span>Texto de demostración</span><span>Ensayo · Muestra</span></div><p>Este contenido permite revisar la ficha y su relación con la lectura. Se sustituirá al incorporar las obras completas.</p>'+btn('Comenzar a leer ↓',True)+'</div>','Serifa para la voz editorial, metadatos separados del título. Sin atribuir una obra ficticia a Paynalton.')
add(24,'Índice del texto','Lectura','<div class="reading-split"><aside class="toc">'+label('EN ESTA PÁGINA')+'<a href="#reading-sample">01 · Una pregunta</a><a class="active" href="#reading-sample">02 · Observar con atención</a><a href="#reading-sample">03 · Volver a pensar</a></aside><div class="paper prose" id="reading-sample"><h2>Observar con atención</h2><p>Una muestra de lectura permite observar el ritmo de la página: la relación entre el título, los párrafos y el espacio que los separa.</p><p>La estructura debe acompañar al texto y ayudar a encontrar el camino de regreso.</p></div></div>','Índice lateral en escritorio y anterior al texto en móvil. Encabezados de muestra con enlaces locales.')
add(25,'Preferencias de lectura','Lectura','<div class="reader-tools">'+label('TU ESPACIO DE LECTURA')+'<label>Tamaño del texto<input type="range" min="16" max="26" value="20" data-reader-size></label><div class="actions">'+btn('Pergamino',True)+btn('Obsidiana',True)+'</div></div><div class="paper prose adjustable"><h2>Leer con espacio.</h2><p>La medida de la columna y el tamaño de letra acompañan el ritmo personal. Este párrafo permite probar el ajuste.</p></div>','El deslizador modifica el texto de ejemplo. La persistencia y los temas del lector son ampliaciones posteriores.','Posterior')
add(26,'Progreso y continuación','Lectura',heading('Retoma el hilo.','LECTURA LOCAL')+'<div class="progress-track"><span></span></div><div class="flex"><strong>35 %</strong><span class="muted">Ejemplo de progreso</span></div><div class="resume">'+label('ÚLTIMA POSICIÓN')+'<h3>Una pregunta · Capítulo 2</h3><p>El avance se conserva solo en este navegador.</p><div class="actions">'+btn('Continuar leyendo →')+btn('Reiniciar',True)+'</div></div>','Estado visual ilustrativo, no una lectura registrada. Nunca promete sincronización entre dispositivos.','Posterior')
add(27,'Notas y referencias','Lectura','<div class="paper prose"><h2>Dar lugar a las fuentes.</h2><p>El texto mantiene su continuidad, mientras una llamada permite consultar una aclaración.<sup><a href="#note-1" id="note-call">1</a></sup></p><div class="divider"></div><ol class="footnotes"><li id="note-1">Nota de demostración: aquí se incluye la referencia o explicación correspondiente. <a href="#note-call" aria-label="Volver al texto">↩</a></li></ol></div>','Enlaces de ida y vuelta. Las notas están en el documento, disponibles sin panel emergente.')
add(28,'Serie y capítulos','Lectura',heading('Un recorrido, varias partes.','OBRA DE EJEMPLO')+'<div class="chapters">'+row('Una pregunta','01 · Inicio del recorrido','Leer ↗')+row('Observar con atención','02 · Capítulo actual','Aquí')+row('Volver a pensar','03 · Continuación','Leer ↗')+'</div><div class="chapter-nav"><button>← Capítulo anterior</button><button>Ver índice</button><button>Capítulo siguiente →</button></div>','Navegación básica necesaria ahora para probar el lector. Los capítulos son ejemplos; las funciones enriquecidas de series pueden añadirse después.')
add(29,'Cita y formatos','Lectura',heading('Lleva contigo la referencia.','CITAR Y DESCARGAR')+'<div class="citation">Texto de demostración. Una pregunta al comienzo. Ejemplo de formato de cita.</div><div class="actions">'+btn('Copiar referencia')+btn('PDF ↓',True)+btn('EPUB ↓',True)+'</div><p class="small muted">Muestra visual; no hay documentos asociados a este ejemplo.</p>','Estudio del módulo ampliado de citas y formatos. No se simulan descargas disponibles. Las descargas existentes del sitio se conservan.','Posterior')
add(30,'Etiquetas temáticas','Exploración',heading('Cada etiqueta abre un camino.','TEMAS Y CAPACIDADES')+'<div class="term-rows"><div><small>TEMA</small>'+tag('Inteligencia y humanidad ↗')+tag('Creación editorial ↗')+'</div><div><small>CAPACIDAD</small>'+tag('Integración de sistemas ↗')+tag('Liderazgo técnico ↗')+'</div><div><small>TECNOLOGÍA</small>'+tag('PHP ↗')+tag('Node.js ↗')+'</div></div>','Familias identificadas por texto además de color. Las etiquetas no equivalen a acreditaciones profesionales.')
add(31,'Ficha de término','Exploración',heading('Integración de sistemas','CAPACIDAD')+'<p class="lead">Conectar aplicaciones, datos y servicios que no fueron concebidos como una sola solución.</p><div class="divider"></div><div class="cards">'+card('Pipila','Desacoplamiento de servicios y procesamiento.')+card('Onix','Transición e integración de una operación.','02')+'</div>','Definición breve y contenidos agrupados. Las jerarquías solo aparecen cuando tienen sentido editorial.')
add(32,'Contenidos relacionados','Exploración',heading('Seguir explorando.','RELACIONES CON CONTEXTO')+'<div class="relationship"><span class="relation-word">APOYA LA CREACIÓN DE</span><h3>GUACAMAYA <span>→</span> Cuando la tostadora te responde</h3><p>La herramienta acompañó el proceso de creación del libro, bajo dirección autoral.</p></div><div class="relationship"><span class="relation-word">IMPLEMENTA</span><h3>PERICO <span>→</span> LORO</h3><p>Memoria y contexto para trabajar con agentes en el desarrollo.</p></div>','Los vínculos explican su motivo. No se muestran relaciones a las obras aplazadas.')
add(33,'Explorador de conexiones','Exploración',heading('Ideas que se encuentran.','EXPLORAR CONEXIONES')+'<div class="network"><div class="node center">Creación editorial</div><div class="node left">GUACAMAYA</div><div class="node right">Libro publicado</div><div class="node bottom">Memoria y contexto</div></div><div class="network-list">'+row('GUACAMAYA → Libro publicado','Apoya la creación editorial')+'</div>','Composición del grafo acompañada de lista equivalente. Muestra estática; no presupone arrastrar ni hacer zoom.','Posterior')
add(34,'Panel de contacto','Contacto',heading('Hablemos del proyecto.','CONTACTO')+'<p>Cuéntame qué intentas resolver, en qué punto estás y qué esperas conseguir.</p><div class="email">cxescalona@gmail.com</div><div class="actions"><a class="button" href="mailto:cxescalona@gmail.com">Escribirme por correo ↗</a><button class="button secondary" data-copy="cxescalona@gmail.com">Copiar correo</button></div><p class="small muted">El enlace abre tu aplicación de correo.</p><p role="status" class="copy-status"></p>','Correo seleccionable, enlace real y copia con confirmación. Sin recepción remota de mensajes.')
add(35,'Compartir contenido','Contacto',heading('Una conversación puede seguir.','COMPARTIR')+'<div class="share-box"><label>Enlace público<input readonly value="https://paynalton.tech/es/"></label><button class="button" data-copy="https://paynalton.tech/es/">Copiar enlace</button></div><p role="status" class="copy-status"></p><p class="small muted">También puedes seleccionar y copiar la dirección.</p>','Control sencillo y confirmación accesible. La API de compartir del sistema se incorporará cuando esté disponible.')
add(36,'Repositorios destacados','Comunidad',heading('Código que se puede recorrer.','CONTRIBUCIONES')+'<article class="repo"><div class="flex"><span>⌘ / paynalton</span>'+tag('Público')+'</div><h3>Proyecto de ejemplo</h3><p>Descripción editorial de la aportación y del propósito del repositorio.</p><div class="divider"></div><span class="textlink">Ver repositorio ↗</span></article>','Tarjeta ilustrativa sin métricas inventadas. Solo se incorporan repositorios públicos seleccionados, nunca los privados.','Posterior')
add(37,'Publicaciones seleccionadas','Comunidad',heading('La idea continúa fuera de aquí.','OTROS ESPACIOS')+'<div class="cards">'+card('Una conversación sobre tecnología','Resumen editorial de una publicación seleccionada.','LINKEDIN')+card('Preguntas para compartir','Contexto de una conversación externa.','REDDIT',True)+'</div>','Ejemplos de formato, no publicaciones atribuidas. Selección local y enlaces; sin feed automático.','Posterior')
add(38,'Video bajo demanda','Lectura','<div class="video-poster"><span class="play">▶</span>'+label('VIDEO DE EJEMPLO')+'<h2>Una explicación<br>con su contexto.</h2></div><details class="transcript"><summary>Leer transcripción</summary><p>Aquí se muestra la transcripción del contenido seleccionado.</p></details>','Propuesta para video servido por el sitio o enlace externo identificado. No carga un reproductor remoto ni introduce servicios excluidos.','Posterior')
add(39,'Suscripción RSS','Comunidad',heading('Sigue las nuevas publicaciones.','RSS')+'<p>Recibe las novedades en tu lector de feeds, sin registrarte en el sitio.</p><div class="share-box"><input aria-label="Dirección RSS" readonly value="https://paynalton.tech/rss.xml"><button class="button secondary" data-copy="https://paynalton.tech/rss.xml">Copiar dirección</button></div><p role="status" class="copy-status"></p>','Módulo ampliado de acceso al feed existente. Sin newsletter ni recopilación de correos.','Posterior')
