js='''document.querySelectorAll('.menu-toggle').forEach(b=>{const m=document.getElementById(b.getAttribute('aria-controls'));b.addEventListener('click',()=>{m.hidden=!m.hidden;b.setAttribute('aria-expanded',String(!m.hidden))});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden){m.hidden=true;b.setAttribute('aria-expanded','false');b.focus()}})});
document.querySelectorAll('[data-search]').forEach(i=>i.addEventListener('input',()=>{let count=0;document.querySelectorAll('.search-items .row').forEach(r=>{r.hidden=!r.textContent.toLowerCase().includes(i.value.toLowerCase());if(!r.hidden)count++});document.querySelector('.no-search').hidden=!!count}));
document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{const s=document.querySelector('.copy-status');try{await navigator.clipboard.writeText(b.dataset.copy);s.textContent='Copiado.'}catch{s.textContent='Selecciona el texto y cópialo manualmente.'}}));
document.querySelectorAll('[data-reader-size]').forEach(i=>i.addEventListener('input',()=>document.querySelector('.adjustable').style.fontSize=i.value+'px'));
document.querySelectorAll('[data-clear]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('select').forEach(s=>s.selectedIndex=s.options.length-1);const c=document.querySelector('.selected');if(c)c.hidden=true}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.gallery-card').forEach(c=>c.hidden=b.dataset.filter!=='Todos'&&c.dataset.state!==b.dataset.filter)}));
document.querySelectorAll('.stage button:not([data-copy]):not([data-clear]):not(.menu-toggle)').forEach(b=>b.addEventListener('click',()=>{let t=document.querySelector('.local-feedback');if(!t){t=document.createElement('div');t.className='local-feedback';t.setAttribute('role','status');document.body.append(t)}t.textContent='Propuesta visual: esta acción se implementará en el sitio.';clearTimeout(window.feedbackTimer);window.feedbackTimer=setTimeout(()=>t.remove(),3000)}));'''
(ROOT/'assets/demo.js').write_text(js)
